#!/usr/bin/env node
// Generates CSS custom properties and a TypeScript module from src/tokens.json, and the Swift tokens of the
// native apps (apps/native-kit FoleviDesign: colours, chrome, glass, shadows, spacing, radii, type, motion, the
// note themes' colours from covers/covers.json and the folder colours, docs/NATIVE_APP_PLAN.md section 7).
// `--check` fails when generated files are stale (used in CI).
import { readFileSync, writeFileSync, mkdirSync, existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, "..");
const repo = resolve(root, "../..");
const tokens = JSON.parse(readFileSync(resolve(root, "src/tokens.json"), "utf8"));
const check = process.argv.includes("--check");

const kebab = (s) => s.replace(/([a-z0-9])([A-Z])/g, "$1-$2").replace(/\./g, "_").toLowerCase();
const HEADER = "Generated by packages/design-tokens/scripts/build.mjs. Do not edit.";

const stripMeta = (obj) => Object.fromEntries(Object.entries(obj).filter(([k]) => !k.startsWith("$")));

function cssVars(obj, prefix, unit = "") {
  return Object.entries(obj).map(([k, v]) => `  --${prefix}-${kebab(k)}: ${v}${typeof v === "number" ? unit : ""};`);
}

const shadowCss = (layers) =>
  layers.map(([x, y, blur, spread, c, inset]) => `${inset ? "inset " : ""}${x}px ${y}px ${blur}px ${spread}px ${c}`).join(", ");
const shadowVars = (theme) => Object.entries(tokens.shadow[theme]).map(([k, v]) => `  --shadow-${kebab(k)}: ${shadowCss(v)};`);

/** The UI type scale's roles (largeTitle → --type-large-title, title1 → --type-title-1) with their line heights. */
const roleName = (r) => kebab(r).replace(/(\d)/, "-$1");
const typeVars = (scale) => Object.entries(scale).flatMap(([r, { size, leading }]) => [`  --type-${roleName(r)}: ${size}px;`, `  --type-${roleName(r)}-leading: ${leading}px;`]);

function buildCss() {
  const { color, space, radius, font, layout, motion } = tokens;
  const light = [...cssVars(color.light, "color"), ...shadowVars("light")].join("\n");
  const dark = [...cssVars(color.dark, "color"), ...shadowVars("dark")].join("\n");
  const shared = [
    ...Object.entries(stripMeta(space)).map(([k, v]) => `  --space-${k.replace(".", "_")}: ${v}px;`),
    ...cssVars(radius, "radius", "px"),
    ...typeVars(font.role.desktop),
    `  --type-input-min: ${font.inputMin}px;`,
    ...Object.entries(font.lineHeight).map(([k, v]) => `  --leading-${kebab(k)}: ${v};`),
    ...Object.entries(font.weight).map(([k, v]) => `  --weight-${kebab(k)}: ${v};`),
    ...Object.entries(font.tracking).map(([k, v]) => `  --tracking-${kebab(k)}: ${v}em;`),
    ...Object.entries(font.family).map(([k, v]) => `  --font-family-${kebab(k)}: "${v}";`),
    ...cssVars(layout, "layout", "px"),
    ...Object.entries(motion).map(([k, v]) => `  --motion-${kebab(k)}: ${typeof v === "number" ? `${v}ms` : v};`),
  ].join("\n");
  const chromeLight = cssVars(stripMeta(tokens.chrome.light), "color").join("\n");
  const chromeDark = cssVars(stripMeta(tokens.chrome.dark), "color").join("\n");
  const glassLight = cssVars(stripMeta(tokens.glass.light), "glass").join("\n");
  const glassDark = cssVars(stripMeta(tokens.glass.dark), "glass").join("\n");
  return `/* ${HEADER} */
:root {
${shared}
  color-scheme: light;
${light}
}

/* The iPhone and iPad apps (and Android's): Apple's default Dynamic Type sizes for the same roles. */
:root:is([data-iphone], [data-native]) {
${typeVars(font.role.ios).join("\n")}
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    color-scheme: dark;
${dark.replace(/^ {2}/gm, "    ")}
  }
}

:root[data-theme="dark"] {
  color-scheme: dark;
${dark}
}

/* Neutral app chrome (tokens.chrome): inside the product. AccountGate and the admin console set
   data-chrome="neutral"; server-rendered pages (sign in, shared notes) carry a .ui-neutral-chrome element. */
:root[data-chrome="neutral"],
:root:has(.ui-neutral-chrome) {
${chromeLight}
}

:root[data-chrome="neutral"][data-theme="dark"],
:root[data-theme="dark"]:has(.ui-neutral-chrome) {
${chromeDark}
}

/* Glass (tokens.glass). */
:root {
${glassLight}
}

:root[data-theme="dark"] {
${glassDark}
}

/* .ui-invert: one part of the page in the other theme, everything else unchanged (the Vault's panel: dark in
   light mode, light in dark mode). Colours, shadows, the app's neutral chrome and glass, so its contents follow. */
.ui-invert {
  color-scheme: dark;
${dark}
${chromeDark}
${glassDark}
}

:root[data-theme="dark"] .ui-invert {
  color-scheme: light;
${light}
${chromeLight}
${glassLight}
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) .ui-invert {
    color-scheme: light;
${[light, chromeLight, glassLight].join("\n").replace(/^ {2}/gm, "    ")}
  }
}

@media (prefers-reduced-motion: reduce) {
  :root {
    --motion-fast: 0ms;
    --motion-base: 0ms;
    --motion-slow: 0ms;
    --motion-page: 0ms;
  }
}
`;
}

function buildTs() {
  return `// ${HEADER}
export const tokens = ${JSON.stringify({ ...tokens, $description: undefined, contrastPairs: undefined }, null, 2)} as const;

export type ColorToken = keyof typeof tokens.color.light;
export const documentAccents = ["accent", "moss", "marigold", "plum", "coral"] as const;
export type DocumentAccent = (typeof documentAccents)[number];
`;
}

// Swift (apps/native-kit/Sources/FoleviDesign/Generated/Tokens.swift). Colours become RGBA literals in
// light/dark pairs; FoleviDesign turns them into dynamic SwiftUI, UIKit and AppKit colours.
function rgba(value) {
  const v = String(value).trim();
  let m = v.match(/^#([0-9a-f]{6})([0-9a-f]{2})?$/i);
  if (m) {
    const n = parseInt(m[1], 16);
    return [(n >> 16) & 255, (n >> 8) & 255, n & 255, m[2] ? parseInt(m[2], 16) / 255 : 1];
  }
  m = v.match(/^rgba?\(\s*([\d.]+)\s*,\s*([\d.]+)\s*,\s*([\d.]+)\s*(?:,\s*([\d.]+)\s*)?\)$/i);
  if (m) return [Number(m[1]), Number(m[2]), Number(m[3]), m[4] === undefined ? 1 : Number(m[4])];
  throw new Error(`Can't read the colour ${v}`);
}
const num = (n) => (Number.isInteger(n) ? `${n}` : `${Number(n.toFixed(4))}`);
const swiftRGBA = (value) => {
  const [r, g, b, a] = rgba(value);
  return `RGBA(${r}, ${g}, ${b}${a === 1 ? "" : `, ${num(a)}`})`;
};
// Spacing steps are numbers ("0.5" becomes s0_5); other keys are already camelCase.
const swiftName = (k) => (/^[0-9]/.test(k) ? `s${k.replace(".", "_")}` : k.replace(/[^A-Za-z0-9]+(.)/g, (_, c) => c.toUpperCase()));
const swiftString = (s) => JSON.stringify(String(s));

function buildSwift() {
  const { color, chrome, glass, space, spaceRoles, radius, font, layout, motion, shadow } = tokens;
  const covers = JSON.parse(readFileSync(resolve(root, "covers/covers.json"), "utf8"));
  const folders = JSON.parse(readFileSync(resolve(root, "covers/folder-colors.json"), "utf8"));
  const legacy = JSON.parse(readFileSync(resolve(root, "covers/folder-colors-legacy.json"), "utf8"));
  const pairs = (light, dark) =>
    Object.keys(light)
      .filter((k) => !k.startsWith("$"))
      .map((k) => `        public static let ${swiftName(k)} = ColorPair(light: ${swiftRGBA(light[k])}, dark: ${swiftRGBA(dark[k])})`)
      .join("\n");
  // The neutral chrome overrides some of the warm palette's tokens; the rest (ember, moss, destructive, ...) carry over.
  const chromeLight = { ...color.light, ...stripMeta(chrome.light) };
  const chromeDark = { ...color.dark, ...stripMeta(chrome.dark) };
  const shadows = Object.keys(shadow.light)
    .map((k) => {
      const layers = (theme) =>
        shadow[theme][k].map(([x, y, blur, spread, c, inset]) => `ShadowLayer(x: ${x}, y: ${y}, blur: ${blur}, spread: ${spread}, color: ${swiftRGBA(c)}${inset ? ", inset: true" : ""})`).join(", ");
      return `        public static let ${swiftName(k)} = ShadowPair(light: [${layers("light")}], dark: [${layers("dark")}])`;
    })
    .join("\n");
  const numbers = (obj) => Object.entries(stripMeta(obj)).map(([k, v]) => `        public static let ${swiftName(k)}: CGFloat = ${num(v)}`).join("\n");
  // The type scale's roles ({ size, leading } per platform) and the spacing roles, as the web's CSS has them.
  const roles = (scale) => Object.entries(scale).map(([k, { size, leading }]) => `            public static let ${swiftName(k)} = TypeMetrics(size: ${num(size)}, leading: ${num(leading)})`).join("\n");
  const spaceRole = (platform) =>
    Object.entries(stripMeta(spaceRoles))
      .filter(([, v]) => typeof v[platform] === "number")
      .map(([k, v]) => `            public static let ${swiftName(k)}: CGFloat = ${num(v[platform])}`)
      .join("\n");
  const bezier = String(motion.easing).match(/cubic-bezier\(([^)]+)\)/)[1].split(",").map((x) => num(Number(x.trim())));
  const themes = covers
    .map(
      (c) =>
        `        NoteTheme(id: ${swiftString(c.id)}, name: ${swiftString(c.name)}, paper: ${swiftRGBA(c.paper)}, ink: ${swiftRGBA(c.ink)}, paperDark: ${swiftRGBA(c.paperDark)}, inkDark: ${swiftRGBA(c.inkDark)}, accent: ${swiftRGBA(c.accent)}, accentDark: ${swiftRGBA(c.accentDark)}, deepCover: ${c.tone === "deep"})`,
    )
    .join(",\n");
  const folderList = folders.map((f) => `        FolderColor(id: ${swiftString(f.id)}, name: ${swiftString(f.name)}, color: ${swiftRGBA(f.hex)})`).join(",\n");
  const legacyList = Object.entries(legacy).map(([k, v]) => `        ${swiftString(k)}: ${swiftString(v)}`).join(",\n");
  return `// ${HEADER}
// Source: packages/design-tokens/src/tokens.json, covers/covers.json, covers/folder-colors*.json.
import CoreGraphics

public enum FoleviTokens {
    /// The warm palette (marketing site, and the tokens the neutral chrome doesn't override).
    public enum Warm {
${pairs(color.light, color.dark)}
    }

    /// Neutral app chrome (docs/DESIGN_SYSTEM.md "Neutral app chrome"): white / near-black, notes carry the colour.
    public enum Chrome {
${pairs(chromeLight, chromeDark)}
    }

    /// Glass: translucent chrome over the canvas.
    public enum Glass {
${pairs(stripMeta(glass.light), stripMeta(glass.dark))}
    }

    public enum Shadow {
${shadows}
    }

    public enum Space {
${numbers(space)}
    }

    public enum Radius {
${numbers(radius)}
    }

    /// The UI type scale (font.role, docs/DESIGN_SYSTEM.md "Type scale"): Desktop is the web app's compact scale,
    /// which Folevi for Mac draws as is; Ios is Apple's default Dynamic Type sizes for the iPhone and iPad apps.
    public enum TypeScale {
        public enum Desktop {
${roles(font.role.desktop)}
        }
        public enum Ios {
${roles(font.role.ios)}
        }
    }

    /// The note's own typography (font.document), outside the UI scale.
    public enum DocumentType {
${numbers(font.document)}
    }

    /// CSS font weights (100 to 900); the bundled variable fonts draw any of them.
    public enum FontWeight {
${numbers(font.weight)}
    }

    /// The smallest text field font size on a touch screen.
    public static let inputMinSize: CGFloat = ${num(font.inputMin)}

    /// Spacing by role (spaceRoles, docs/DESIGN_SYSTEM.md "Spacing").
    public enum SpaceRole {
        public enum Desktop {
${spaceRole("desktop")}
        }
        public enum Ios {
${spaceRole("ios")}
        }
    }

    /// Legacy sizes (font.size), read by the iOS text styles until they move to TypeScale.Ios.
    public enum FontSize {
${numbers(font.size)}
    }

    public enum LineHeight {
${numbers(font.lineHeight)}
    }

    /// Letter spacing in em.
    public enum Tracking {
${numbers(font.tracking)}
    }

    public enum FontFamily {
${Object.entries(font.family).map(([k, v]) => `        public static let ${swiftName(k)} = ${swiftString(v)}`).join("\n")}
    }

    public enum Layout {
${numbers(layout)}
    }

    /// Durations in seconds, and the easing curve's control points.
    public enum Motion {
${Object.entries(motion).filter(([, v]) => typeof v === "number").map(([k, v]) => `        public static let ${swiftName(k)}: Double = ${num(v / 1000)}`).join("\n")}
        public static let easing: (CGFloat, CGFloat, CGFloat, CGFloat) = (${bezier.join(", ")})
    }

    /// The built-in note themes' colours (art-01 ...), for card covers and previews drawn natively.
    public static let noteThemes: [NoteTheme] = [
${themes}
    ]

    /// Folder colours (25), in picker order.
    public static let folderColors: [FolderColor] = [
${folderList}
    ]

    /// Earlier folder colour ids and the colour each shows now.
    public static let legacyFolderColors: [String: String] = [
${legacyList}
    ]
}
`;
}

const outputs = [
  [resolve(root, "generated/tokens.css"), buildCss()],
  [resolve(root, "generated/tokens.ts"), buildTs()],
  [resolve(repo, "apps/native-kit/Sources/FoleviDesign/Generated/Tokens.swift"), buildSwift()],
];

let stale = false;
for (const [file, content] of outputs) {
  if (check) {
    if (!existsSync(file) || readFileSync(file, "utf8") !== content) {
      console.error(`stale: ${file}`);
      stale = true;
    }
    continue;
  }
  mkdirSync(dirname(file), { recursive: true });
  writeFileSync(file, content);
  console.log(`wrote ${file.replace(repo + "/", "")}`);
}
if (stale) {
  console.error("Design tokens are stale. Run `pnpm tokens`.");
  process.exit(1);
}
